"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[3588],{9092(a){a.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/AndroidCameraParameters/es/","label":"Resumen de la Aplicaci\xf3n","docId":"overview","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/development","label":"Documentaci\xf3n para Desarrolladores","docId":"development","unlisted":false},{"type":"category","label":"Mastering Android Camera2 API","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/AndroidCameraParameters/es/camera2/welcome-to-android-camera2","label":"Cap\xedtulo 1: Bienvenido a Android Camera2","docId":"camera2/welcome-to-android-camera2","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/understanding-smartphone-cameras","label":"Cap\xedtulo 2: Entendiendo las c\xe1maras de los smartphones","docId":"camera2/understanding-smartphone-cameras","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/what-can-modern-smartphone-cameras-do","label":"Cap\xedtulo 3: Fotograf\xeda moderna con smartphones","docId":"camera2/what-can-modern-smartphone-cameras-do","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/exploring-your-phones-camera","label":"Cap\xedtulo 4: Explore su propio tel\xe9fono","docId":"camera2/exploring-your-phones-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/creating-your-first-camera2-project","label":"Cap\xedtulo 5: Creando su primer proyecto Camera2","docId":"camera2/creating-your-first-camera2-project","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/discovering-cameras","label":"Cap\xedtulo 6: Descubriendo c\xe1maras","docId":"camera2/discovering-cameras","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/opening-a-camera","label":"Cap\xedtulo 7: Abriendo una c\xe1mara","docId":"camera2/opening-a-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/showing-camera-preview","label":"Cap\xedtulo 8: Mostrando la vista previa de la c\xe1mara","docId":"camera2/showing-camera-preview","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/taking-photos","label":"Cap\xedtulo 9: Tomando fotos","docId":"camera2/taking-photos","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/the-camera2-pipeline","label":"Cap\xedtulo 10: La tuber\xeda de Camera2","docId":"camera2/the-camera2-pipeline","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/capture-types","label":"Cap\xedtulo 11: Tipos de captura","docId":"camera2/capture-types","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/cameracharacteristics-deep-dive","label":"Cap\xedtulo 12: Inmersi\xf3n profunda en CameraCharacteristics","docId":"camera2/cameracharacteristics-deep-dive","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/exposure","label":"Cap\xedtulo 13: Exposici\xf3n","docId":"camera2/exposure","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/manual-exposure-in-camera2","label":"Cap\xedtulo 14: Exposici\xf3n manual en Camera2","docId":"camera2/manual-exposure-in-camera2","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/focus","label":"Cap\xedtulo 15: Enfoque","docId":"camera2/focus","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/white-balance-and-color","label":"Cap\xedtulo 16: Balance de blancos y color","docId":"camera2/white-balance-and-color","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/3a-pipeline","label":"Cap\xedtulo 17: La tuber\xeda 3A","docId":"camera2/3a-pipeline","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/raw-photography","label":"Cap\xedtulo 18: Fotograf\xeda RAW","docId":"camera2/raw-photography","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/high-speed-video","label":"Cap\xedtulo 19: Video de alta velocidad","docId":"camera2/high-speed-video","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/multi-camera","label":"Cap\xedtulo 20: C\xe1mara m\xfaltiple","docId":"camera2/multi-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/hdr-and-ultra-hdr","label":"Cap\xedtulo 21: HDR y Ultra HDR","docId":"camera2/hdr-and-ultra-hdr","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/camera-extensions","label":"Cap\xedtulo 22: Extensiones de c\xe1mara","docId":"camera2/camera-extensions","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/zero-shutter-lag-and-reprocessing","label":"Cap\xedtulo 23: Retraso de Obturador Cero y Reprocesamiento","docId":"camera2/zero-shutter-lag-and-reprocessing","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/camerax","label":"Cap\xedtulo 24: CameraX","docId":"camera2/camerax","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/native-camera-development","label":"Cap\xedtulo 25: Desarrollo de c\xe1mara nativa","docId":"camera2/native-camera-development","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/asynchronous-camera-programming","label":"Cap\xedtulo 26: Programaci\xf3n de C\xe1mara As\xedncrona","docId":"camera2/asynchronous-camera-programming","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/camera-testing","label":"Cap\xedtulo 27: Pruebas de c\xe1mara","docId":"camera2/camera-testing","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/camera2-architecture","label":"Cap\xedtulo 28: Arquitectura de Camera2","docId":"camera2/camera2-architecture","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/es/camera2/camera-metadata-encyclopedia","label":"Enciclopedia de metadatos de c\xe1mara","docId":"camera2/camera-metadata-encyclopedia","unlisted":false}],"href":"/AndroidCameraParameters/es/category/mastering-android-camera2-api"},{"type":"link","href":"/AndroidCameraParameters/es/data-safety","label":"Gu\xeda de Seguridad de Datos","docId":"data-safety","unlisted":false}]},"docs":{"camera2/3a-pipeline":{"id":"camera2/3a-pipeline","title":"Cap\xedtulo 17: La tuber\xeda 3A","description":"Orqueste la Exposici\xf3n Autom\xe1tica (AE), el Enfoque Autom\xe1tico (AF) y el Balance de Blancos Autom\xe1tico (AWB) en una secuencia de captura de fotograf\xeda est\xe1tica fiable. Aprenda el disparador de precaptura, los modos de flash, las m\xe1quinas de estado AE/AF y cree c\xf3digo Kotlin de calidad de producci\xf3n que coordine las tres A antes de cada toma.","sidebar":"tutorialSidebar"},"camera2/asynchronous-camera-programming":{"id":"camera2/asynchronous-camera-programming","title":"Cap\xedtulo 26: Programaci\xf3n de C\xe1mara As\xedncrona","description":"Dome el infierno de las devoluciones de llamada (callbacks) de Camera2 utilizando las corrutinas de Kotlin y Flow. Aprenda suspendCancellableCoroutine para operaciones de un solo disparo (openCamera, createCaptureSession, capture), callbackFlow para flujos continuos de ImageReader y CaptureResult, operadores de combinaci\xf3n para interfaces de usuario reactivas y patrones de seguridad de hilos para evitar ANR y bloqueos (deadlocks).","sidebar":"tutorialSidebar"},"camera2/camera-extensions":{"id":"camera2/camera-extensions","title":"Cap\xedtulo 22: Extensiones de c\xe1mara","description":"Utilice CameraExtensionSession para la fotograf\xeda computacional acelerada por el fabricante: modo nocturno, modo retrato Bokeh, extensi\xf3n HDR, retoque facial y modo autom\xe1tico. Consulte CameraExtensionCharacteristics, gestione la latencia y contraste la arquitectura de las sesiones est\xe1ndar frente a las de extensi\xf3n.","sidebar":"tutorialSidebar"},"camera2/camera-metadata-encyclopedia":{"id":"camera2/camera-metadata-encyclopedia","title":"Enciclopedia de metadatos de c\xe1mara","description":"Gu\xeda de referencia completa para todas las claves de metadatos esenciales de CameraCharacteristics, incluyendo las categor\xedas Sensor, Lens, Control, Scaler, Request, Flash, JPEG, Statistics e Info.","sidebar":"tutorialSidebar"},"camera2/camera-testing":{"id":"camera2/camera-testing","title":"Cap\xedtulo 27: Pruebas de c\xe1mara","description":"La gu\xeda completa de pruebas de c\xe1mara en Android. Entienda Camera ITS (Image Test Suite), qu\xe9 validan los fabricantes antes del env\xedo (combinaciones de funciones, pruebas de escena, fusi\xf3n de sensores), las pruebas manuales de CTS Verifier y c\xf3mo escribir sus propias pruebas de instrumentaci\xf3n con simulacros de Mockito y pruebas de nivel de hardware parametrizadas que se ejecutan en CI.","sidebar":"tutorialSidebar"},"camera2/camera2-architecture":{"id":"camera2/camera2-architecture","title":"Cap\xedtulo 28: Arquitectura de Camera2","description":"El gran final de la arquitectura de Camera2. Recorra toda la pila desde su aplicaci\xf3n Kotlin hacia abajo a trav\xe9s de Binder IPC, el Framework, CameraService en nativo, Camera3Device, HAL3 con camera3_device_t, el controlador del kernel V4L2 y, finalmente, el sensor f\xedsico, el ISP, la lente VCM y el hardware del flash. Incluye el requisito de Treble HAL, el adaptador LEGACY HAL1 y CameraDeviceSetup de Android 15. Mapa completo del viaje del lector por capas.","sidebar":"tutorialSidebar"},"camera2/cameracharacteristics-deep-dive":{"id":"camera2/cameracharacteristics-deep-dive","title":"Cap\xedtulo 12: Inmersi\xf3n profunda en CameraCharacteristics","description":"Domine CameraCharacteristics: los metadatos est\xe1ticos inmutables que describen cada c\xe1mara antes de abrirla. Niveles de hardware (LEGACY, LIMITED, FULL, LEVEL_3, EXTERNAL), banderas de capacidad, organizaci\xf3n de claves de metadatos y consultas de capacidad en tiempo de ejecuci\xf3n.","sidebar":"tutorialSidebar"},"camera2/camerax":{"id":"camera2/camerax","title":"Cap\xedtulo 24: CameraX","description":"Domine CameraX, la biblioteca de c\xe1mara de Jetpack con detecci\xf3n del ciclo de vida que envuelve a Camera2. Aprenda la arquitectura UseCase, Camera2Interop para inyectar par\xe1metros manuales y un marco de decisi\xf3n para elegir entre CameraX y Camera2.","sidebar":"tutorialSidebar"},"camera2/capture-types":{"id":"camera2/capture-types","title":"Cap\xedtulo 11: Tipos de captura","description":"Aprenda los tres tipos de captura de Camera2: disparo \xfanico (capture), r\xe1faga (captureBurst) y repetitiva (setRepeatingRequest), adem\xe1s de las plantillas integradas (TEMPLATE_PREVIEW, TEMPLATE_STILL_CAPTURE, TEMPLATE_RECORD y m\xe1s).","sidebar":"tutorialSidebar"},"camera2/creating-your-first-camera2-project":{"id":"camera2/creating-your-first-camera2-project","title":"Cap\xedtulo 5: Creando su primer proyecto Camera2","description":"Configure un proyecto Android Camera2 completo desde cero. Aprenda sobre los permisos de la c\xe1mara, la inicializaci\xf3n de CameraManager, el subprocesamiento en segundo plano con HandlerThread y la configuraci\xf3n del proyecto necesaria para la aceleraci\xf3n de hardware de TextureView.","sidebar":"tutorialSidebar"},"camera2/discovering-cameras":{"id":"camera2/discovering-cameras","title":"Cap\xedtulo 6: Descubriendo c\xe1maras","description":"Enumere y consulte cada c\xe1mara de un dispositivo Android usando CameraCharacteristics. Aprenda la sem\xe1ntica de los ID de c\xe1mara, las direcciones de orientaci\xf3n de la lente (frontal/trasera/externa), las c\xe1maras externas USB OTG y la jerarqu\xeda de niveles de hardware desde LEGACY hasta LEVEL_3.","sidebar":"tutorialSidebar"},"camera2/exploring-your-phones-camera":{"id":"camera2/exploring-your-phones-camera","title":"Cap\xedtulo 4: Explore su propio tel\xe9fono","description":"Utilice la aplicaci\xf3n complementaria Android Camera Parameters para inspeccionar su propio dispositivo. Aprenda a leer los ID de c\xe1mara, comprobar los niveles de hardware, enumerar las c\xe1maras, inspeccionar los formatos compatibles, las velocidades de fotogramas, los rangos de zoom y la capacidad RAW.","sidebar":"tutorialSidebar"},"camera2/exposure":{"id":"camera2/exposure","title":"Cap\xedtulo 13: Exposici\xf3n","description":"Domine los fundamentos de la exposici\xf3n fotogr\xe1fica: el tri\xe1ngulo de exposici\xf3n formado por el ISO, la velocidad de obturaci\xf3n y la apertura. Entienda los pasos de EV, la regla Sunny 16 y c\xf3mo las diferentes combinaciones crean la misma exposici\xf3n con compensaciones creativas.","sidebar":"tutorialSidebar"},"camera2/focus":{"id":"camera2/focus","title":"Cap\xedtulo 15: Enfoque","description":"Domine tanto el enfoque autom\xe1tico como el manual en Android Camera2. Entienda los modos de AF, la m\xe1quina de estados de AF, las secuencias de disparo y captura de un solo toque, el enfoque manual con dioptr\xedas LENS_FOCUS_DISTANCE, la distancia hiperfocal y la construcci\xf3n de un control deslizante SeekBar de enfoque en Kotlin.","sidebar":"tutorialSidebar"},"camera2/hdr-and-ultra-hdr":{"id":"camera2/hdr-and-ultra-hdr","title":"Cap\xedtulo 21: HDR y Ultra HDR","description":"Implemente video HDR10 y HLG a trav\xe9s de DynamicRangeProfiles, y capturas fijas JPEG_R de Android 14 (Ultra HDR ISO 21496-1) con arquitectura de SDR-primario + mapa de ganancia para fotos de alto rango din\xe1mico retrocompatibles","sidebar":"tutorialSidebar"},"camera2/high-speed-video":{"id":"camera2/high-speed-video","title":"Cap\xedtulo 19: Video de alta velocidad","description":"Cree capturas de c\xe1mara lenta a 120 fps y 240 fps con CameraConstrainedHighSpeedCaptureSession, createHighSpeedRequestList y rangos de FPS de StreamConfigurationMap en la API Camera2 de Android","sidebar":"tutorialSidebar"},"camera2/manual-exposure-in-camera2":{"id":"camera2/manual-exposure-in-camera2","title":"Cap\xedtulo 14: Exposici\xf3n manual en Camera2","description":"Tome el control creativo total de la exposici\xf3n con la API Android Camera2. Aprenda a desactivar la exposici\xf3n autom\xe1tica, establecer el ISO manual mediante SENSOR_SENSITIVITY, controlar la velocidad de obturaci\xf3n en nanosegundos con SENSOR_EXPOSURE_TIME y crear ejemplos funcionales en Kotlin para timelapses, exposiciones largas y bracketing.","sidebar":"tutorialSidebar"},"camera2/multi-camera":{"id":"camera2/multi-camera","title":"Cap\xedtulo 20: C\xe1mara m\xfaltiple","description":"Explore los dispositivos de c\xe1mara m\xfaltiple l\xf3gica de Android 9+, los ID de c\xe1mara f\xedsica, la sincronizaci\xf3n de sensores APPROXIMATE frente a CALIBRATED, el cambio de zoom fluido y la captura f\xedsica dual simult\xe1nea mediante OutputConfiguration.setPhysicalCameraId() en la API Camera2","sidebar":"tutorialSidebar"},"camera2/native-camera-development":{"id":"camera2/native-camera-development","title":"Cap\xedtulo 25: Desarrollo de c\xe1mara nativa","description":"P\xe1sese al modo nativo con la pila de c\xe1mara del NDK de Android. Use ACameraManager para abrir c\xe1maras desde C++, vincule la memoria AHardwareBuffer directamente como texturas de Vulkan para una AR con cero copias y entienda la interoperabilidad OpenGL/Vulkan para tuber\xedas de 60 fps. Incluye el contexto de la migraci\xf3n EVS para automoci\xf3n.","sidebar":"tutorialSidebar"},"camera2/opening-a-camera":{"id":"camera2/opening-a-camera","title":"Cap\xedtulo 7: Abriendo una c\xe1mara","description":"Establezca una conexi\xf3n en vivo con un dispositivo de c\xe1mara usando openCamera(). Domine el ciclo de vida de CameraDevice, implemente StateCallback con onOpened/onDisconnected/onError, integre abrir/cerrar con Actividad onPause/onResume y maneje cada c\xf3digo de error de CameraAccessException con control de concurrencia basado en Semaphore.","sidebar":"tutorialSidebar"},"camera2/raw-photography":{"id":"camera2/raw-photography","title":"Cap\xedtulo 18: Fotograf\xeda RAW","description":"Domine el formato RAW_SENSOR, la creaci\xf3n de archivos DNG con DngCreator, los patrones Bayer y la captura simult\xe1nea de RAW+JPEG en la API Camera2 de Android","sidebar":"tutorialSidebar"},"camera2/showing-camera-preview":{"id":"camera2/showing-camera-preview","title":"Cap\xedtulo 8: Mostrando la vista previa de la c\xe1mara","description":"Renderice fotogramas de c\xe1mara en vivo en la pantalla usando TextureView, SurfaceTexture, Surface y CameraCaptureSession. Implemente SurfaceTextureListener, corrija la relaci\xf3n de aspecto con transformaciones de Matrix en configureTransform, construya una CaptureRequest TEMPLATE_PREVIEW e inicie el flujo de vista previa con setRepeatingRequest.","sidebar":"tutorialSidebar"},"camera2/taking-photos":{"id":"camera2/taking-photos","title":"Cap\xedtulo 9: Tomando fotos","description":"Capture fotos fijas de alta calidad con Camera2 usando ImageReader (JPEG), disparador AE de precaptura y m\xe1quina de estados CaptureCallback. Guarde fotos con MediaStore compatible con Almacenamiento con Alcance (Android 10+) y FileOutputStream heredado, recordando siempre cerrar el b\xfafer de Image.","sidebar":"tutorialSidebar"},"camera2/the-camera2-pipeline":{"id":"camera2/the-camera2-pipeline","title":"Cap\xedtulo 10: La tuber\xeda de Camera2","description":"Inmersi\xf3n profunda en la arquitectura de la tuber\xeda de Camera2: CaptureRequest, CaptureResult, colas de solicitudes, retrollamadas de resultados y el flujo de extremo a extremo desde el env\xedo de la solicitud hasta el procesamiento de la HAL y los resultados.","sidebar":"tutorialSidebar"},"camera2/understanding-smartphone-cameras":{"id":"camera2/understanding-smartphone-cameras","title":"Cap\xedtulo 2: Entendiendo las c\xe1maras de los smartphones","description":"Explore el hardware del m\xf3dulo de c\xe1mara que hay dentro de cada smartphone: la lente, el sensor de imagen, el procesador ISP, la diferencia entre RAW y JPEG, los dise\xf1os de c\xe1mara m\xfaltiple y el viaje completo desde los fotones hasta una foto almacenada.","sidebar":"tutorialSidebar"},"camera2/welcome-to-android-camera2":{"id":"camera2/welcome-to-android-camera2","title":"Cap\xedtulo 1: Bienvenido a Android Camera2","description":"Aprenda por qu\xe9 es importante Android Camera2, c\xf3mo se compara con Camera1 y CameraX, qu\xe9 permite y qu\xe9 construir\xe1 en esta serie.","sidebar":"tutorialSidebar"},"camera2/what-can-modern-smartphone-cameras-do":{"id":"camera2/what-can-modern-smartphone-cameras-do","title":"Cap\xedtulo 3: Fotograf\xeda moderna con smartphones","description":"Un recorrido por las funciones computacionales y \xf3pticas de los tel\xe9fonos modernos: HDR, bokeh de retrato, modo nocturno, c\xe1mara lenta, ultra gran angular, teleobjetivo, macro y c\xf3mo la fotograf\xeda computacional fusiona hardware y software.","sidebar":"tutorialSidebar"},"camera2/white-balance-and-color":{"id":"camera2/white-balance-and-color","title":"Cap\xedtulo 16: Balance de blancos y color","description":"Controle el color en Android Camera2 con preajustes de Balance de Blancos Autom\xe1tico y correcci\xf3n de color manual. Aprenda los modos de AWB, la temperatura de color (2000K\u201310000K), transformaciones de color 3\xd73, COLOR_CORRECTION_GAINS y c\xf3digo Kotlin funcional para preajustes de atardecer de tonos c\xe1lidos y balance de blancos manual completo.","sidebar":"tutorialSidebar"},"camera2/zero-shutter-lag-and-reprocessing":{"id":"camera2/zero-shutter-lag-and-reprocessing","title":"Cap\xedtulo 23: Retraso de Obturador Cero y Reprocesamiento","description":"Construya el Retraso de Obturador Cero (ZSL) con almacenamiento en b\xfafer YUV/PRIVATE circular, CONTROL_CAPTURE_INTENT_ZERO_SHUTTER_LAG, sesiones de captura reprocesables a trav\xe9s de InputConfiguration, reinyecci\xf3n de fotogramas ImageWriter y createReprocessCaptureRequest para un procesamiento ISP pesado tras la captura. Tambi\xe9n cubre switchToOffline() para la continuidad del procesamiento en segundo plano.","sidebar":"tutorialSidebar"},"data-safety":{"id":"data-safety","title":"Gu\xeda de Seguridad de Datos","description":"Pr\xe1cticas de seguridad de datos y privacidad para la aplicaci\xf3n Android Camera Parameters. Conozca los permisos de la c\xe1mara y c\xf3mo se manejan los metadatos del hardware.","sidebar":"tutorialSidebar"},"development":{"id":"development","title":"Documentaci\xf3n para Desarrolladores","description":"Arquitectura t\xe9cnica de la aplicaci\xf3n Android Camera Parameters, incluyendo detalles del patr\xf3n MVVM, estructura de la interfaz de usuario con Jetpack Compose y pautas de desarrollo.","sidebar":"tutorialSidebar"},"overview":{"id":"overview","title":"Resumen de la Aplicaci\xf3n","description":"Resumen del panel de Android Camera Parameters y sus funciones clave de diagn\xf3stico, incluyendo detecci\xf3n de nivel de hardware y seguimiento de funciones en tiempo real.","sidebar":"tutorialSidebar"}}}}')}}]);